import { CheckFailed, Circuit, Field, InputError, fromHex, toHex, type Day, type FieldInput, type Json, type Proof, type Prover, type Verifier } from "@blueshift-gg/xark-wasm/client";
import schema from "./age_verification.schema";
export { CheckFailed, Field, InputError, fromHex, toHex };

/** An `Identity` (an input struct). */
export interface Identity {
  born: Day;
  salt: FieldInput;
}

/** A `Policy` (an input struct). */
export interface Policy {
  bornBy: Day;
}

/** Every input of `age_verification`. */
export interface AgeVerificationInputs {
  id: Identity;
  commitment: FieldInput;
  policy: Policy;
  /** `Hash`: its 32 bytes. */
  holder: Uint8Array;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface AgeVerificationPublicInputs {
  commitment: FieldInput;
  policy: Policy;
  /** `Hash`: its 32 bytes. */
  holder: Uint8Array;
}

/** A `Policy`, decoded. */
export interface PolicyValue {
  bornBy: Day;
}

/** The public inputs, decoded from a proof. */
export interface AgeVerificationPublicValues {
  commitment: Field;
  policy: PolicyValue;
  holder: Uint8Array;
}

/** The input structs, by name: what `fields` takes. */
export interface AgeVerificationStructs {
  Identity: Identity;
  Policy: Policy;
}

/**
 * `age_verification`: make a prover or verifier from a URL serving a copy of
 * `target/xark/age_verification/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await AgeVerification.prover("/circuits/age_verification/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await AgeVerification.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const AgeVerification = new Circuit<AgeVerificationInputs, AgeVerificationPublicInputs, AgeVerificationPublicValues, AgeVerificationStructs>({
  name: "age_verification",
  schema,
  decodePublic,
  client: true,
  digest: "4c784f0ca262e3aa5cbeddd02e1c923e",
});

export type AgeVerificationProver = Prover<AgeVerificationInputs, AgeVerificationPublicInputs, AgeVerificationPublicValues, AgeVerificationStructs>;
export type AgeVerificationVerifier = Verifier<AgeVerificationPublicInputs, AgeVerificationPublicValues, AgeVerificationStructs>;
export type AgeVerificationProof = Proof<AgeVerificationPublicValues>;

/** `Policy`'s Rust functions (`#[input] impl Policy`), run from `client.wasm`. */
export const Policy = {
  /**
   * 18 or older on `today`: born on or before the same day 18 years earlier.
   */
  adultOn(today: Day): PolicyValue {
    return decodePolicy(AgeVerification.call<Json<PolicyValue>>("Policy.adult_on", [today]));
  },
};

/** `Identity`'s Rust functions (`#[input] impl Identity`), run from `client.wasm`. */
export const Identity = {
  /**
   * The issuer's commitment: what a verifier sees of the holder, and all it sees.
   */
  commitment(identity: Identity): Field {
    return new Field(AgeVerification.call<Json<Field>>("Identity.commitment", [identity]));
  },
};

function decodePublic(v: Json<AgeVerificationPublicValues>): AgeVerificationPublicValues {
  return {
    commitment: new Field(v.commitment),
    policy: decodePolicy(v.policy),
    holder: fromHex(v.holder),
  };
}

function decodePolicy(v: Json<PolicyValue>): PolicyValue {
  return {
    bornBy: new Date(v.bornBy),
  };
}
